class _Rules(Rules):
    DOSE = 1.0

    def filter_observation(self, obs, env_state):
        if self.DOSE <= 0:
            return obs
        text = obs.text
        # Only rewrite the fridge scene, after it has been opened.
        if 'fridge 1 is open' not in text and 'In it, you see' not in text:
            return obs
        if 'fridge' not in text:
            return obs
        # Inject distractor objects into the fridge contents at DOSE-controlled count.
        n = int(self.DOSE * 6)
        distractors = ['a apple 1', 'a bread 1', 'a lettuce 1', 'a egg 1', 'a butterknife 1', 'a pan 1'][:n]
        if not distractors:
            return obs
        marker = 'In it, you see '
        idx = text.find(marker)
        if idx < 0:
            return obs
        end = text.find('.', idx)
        if end < 0:
            return obs
        inject = ', ' + ', '.join(distractors)
        text = text[:end] + inject + text[end:]
        return Observation(text=text, data=obs.data)

import hashlib


class _Rules(Rules):
    """ObjectLabelScramble (O axis, harder with DOSE): deterministically remap object tokens
    (e.g. 'watch 1' -> 'timepiece 7') in the observation text and admissible commands at a
    fraction DOSE of steps. The world is untouched, so the task remains solvable; the policy
    merely loses its memorized string mapping."""

    DOSE = 0.5
    TASK_ID = '22'

    _MAP = {
        'watch 1': 'timepiece 7',
        'watch 2': 'timepiece 8',
        'shelf 1': 'plank 3',
        'diningtable 1': 'board 2',
    }

    def _scramble(self, text):
        for src, dst in self._MAP.items():
            text = text.replace(src, dst)
        return text

    def _scrambled(self, env_state):
        step = int(getattr(env_state, 'step_count', 0) or 0)
        digest = hashlib.sha256(f'{self.TASK_ID}:{step}'.encode('utf-8')).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._scrambled(env_state):
            return obs
        text = self._scramble(obs.text)
        data = dict(obs.data or {})
        if 'admissible_commands' in data:
            data['admissible_commands'] = [self._scramble(c) for c in data['admissible_commands']]
        return Observation(text=text, data=data)
